t.script:
(function () {
  var searchTimeout = null;

  // --- LOGIC CHIP SEARCH ---
  function initChipInput() {
      var $realInput = $('#real-search-q');
      var $container = $('#chip-container');
      var $visualInput = $('#visual-search-input');
      var currentChips = [];

      // Load giá trị ban đầu từ URL
      var initialVal = $realInput.val();
      if(initialVal) {
          currentChips = initialVal.split(',').map(function(s){ return s.trim(); }).filter(function(s){ return s; });
          renderChips();
      }

      // Hàm vẽ lại toàn bộ chips
      function renderChips() {
          $container.find('.search-chip').remove();
          currentChips.forEach(function(term, index) {
              var $chip = $(
                  '<div class="search-chip">' +
                      '<span>' + $('<div>').text(term).html() + '</span>' +
                      '<span class="btn-close-chip" data-index="' + index + '">&times;</span>' +
                  '</div>'
              );
              $visualInput.before($chip);
          });
          updateRealInput();
      }

      // Cập nhật input ẩn
      function updateRealInput() {
          $realInput.val(currentChips.join(', '));
      }

      // Thêm chip mới
      window.addSearchChip = function(term) {
          term = term.trim().replace(/,/g, ''); // Loại bỏ dấu phẩy
          if(term && !currentChips.includes(term)) {
              currentChips.push(term);
              renderChips();
          }
          $visualInput.val('');
          $visualInput.focus();
      }

      // Xóa chip
      $container.on('click', '.btn-close-chip', function() {
          var idx = $(this).data('index');
          currentChips.splice(idx, 1);
          renderChips();
          $visualInput.focus();
      });

      // Xử lý phím Backspace, Enter, Comma
      $visualInput.on('keydown', function(e) {
          var val = $(this).val();
          if(e.key === 'Backspace' && val === '' && currentChips.length > 0) {
              currentChips.pop();
              renderChips();
          } else if (e.key === 'Enter') {
              e.preventDefault();
              if (val.trim()) {
                  addSearchChip(val);
                  // Nếu nhấn Enter khi đang gõ -> Thêm chip và tìm luôn
                  $('#search-form').submit();
              } else {
                  // Nếu input rỗng -> Tìm kiếm với các chip hiện tại
                  $('#search-form').submit();
              }
          } else if (e.key === ',') {
              e.preventDefault();
              if (val.trim()) {
                  addSearchChip(val);
              }
          }
      });

      // Focus input khi click wrapper
      $container.on('click', function(e) {
          if(e.target === this) $visualInput.focus();
      });
  }

  // --- LOGIC GỢI Ý ---
  function debounce(func, wait) {
    return function() {
      var context = this, args = arguments;
      clearTimeout(searchTimeout);
      searchTimeout = setTimeout(function() { func.apply(context, args); }, wait);
    };
  }

  function searchProducts(term, callback) {
    $.ajax({
      url: "/search_stock/suggest",
      type: "POST", dataType: "json", contentType: "application/json",
      data: JSON.stringify({ jsonrpc: "2.0", method: "call", params: { q: term }, id: new Date().getTime() }),
      success: function(resp) {
        var result = (resp && resp.result) ? resp.result : {};
        callback(result.products || []);
      }
    });
  }

  function renderSuggestions(products) {
    var $dropdown = $('#search-suggestions');
    if (!products || products.length === 0) {
      $dropdown.hide().empty();
      return;
    }
    var html = '';
    products.forEach(function(p) {
       // Dùng TÊN để tìm kiếm
       var displayName = p.name || p.default_code || '';

       html += '<div class="suggestion-item border-bottom p-2" data-name="' + displayName + '" style="cursor:pointer;">';
       html += '  <div class="d-flex align-items-center">';
       // Ảnh
       if (p.image_url) {
           html += '<img src="' + p.image_url + '" class="rounded border me-2 flex-shrink-0" style="width:40px; height:40px; object-fit:cover;"/>';
       } else {
           html += '<div class="rounded border me-2 bg-light d-flex align-items-center justify-content-center flex-shrink-0" style="width:40px; height:40px;"><i class="fa fa-cube text-muted"></i></div>';
       }
       // Thông tin text
       html += '    <div class="flex-grow-1 overflow-hidden">';
       html += '      <div class="fw-bold text-dark text-truncate" style="font-size:0.9rem;">' + (p.default_code || '') + '</div>';
       html += '      <div class="text-muted text-truncate small">' + (p.name || '') + '</div>';
       html += '    </div>';

       // Icon mũi tên để gợi ý là "Chọn cái này"
       html += '    <div class="ms-2 text-primary"><i class="fa fa-angle-right"></i></div>';

       html += '  </div>';
       html += '</div>';
    });
    $dropdown.html(html).show();
  }

  // --- MAIN INIT ---
  $(document).ready(function() {
    initChipInput(); // Setup UI

    var $visualInput = $('#visual-search-input');
    var $dropdown = $('#search-suggestions');

    // Input debounce
    $visualInput.on('input', debounce(function() {
      var term = $(this).val().trim();
      if (term.length >= 2) {
        searchProducts(term, renderSuggestions);
      } else {
        $dropdown.hide();
      }
    }, 300));

    // >>> CLICK GỢI Ý -> AUTO SUBMIT <<<
    $(document).on('click', '.suggestion-item', function() {
      var name = $(this).data('name');
      if (name) {
        // 1. Thêm chip vào ô tìm kiếm
        window.addSearchChip(name);

        // 2. Ẩn dropdown
        $dropdown.hide();

        // 3. TỰ ĐỘNG SUBMIT FORM NGAY LẬP TỨC
        $('#search-form').submit();
      }
    });

    // Click ngoài -> đóng dropdown
    $(document).on('click', function(e) {
      if (!$(e.target).closest('#chip-container, #search-suggestions').length) {
        $dropdown.hide();
      }
    });

    // Logic mở rộng chi tiết (không đổi)
    $(document).on('click', '.btn-expand', function () {
       var $btn = $(this);
       var pid = $btn.data('pid');
       var isCombo = String($btn.data('is-combo')) === 'true';
       var $row = $btn.closest('tr');
       var $next = $row.next();

       if ($next.length && $next.hasClass('detail-row') && $next.is(':visible')) {
         $next.remove();
         $btn.html('<i class="fa fa-plus"></i>');
         return;
       }

       var colCount = $row.children('td').length;
       var $detail = $('<tr class="detail-row bg-white"><td colspan="' + colCount + '" class="p-3 shadow-inset"><div class="d-flex align-items-center"><span class="spinner-border spinner-border-sm me-2"></span>Đang tải dữ liệu...</div></td></tr>');
       $row.after($detail);
       $btn.html('<i class="fa fa-minus"></i>');

       var currentWid = $('select[name="warehouse_id"]').val() || '';
       var detailMode = isCombo ? 'per_warehouse' : null;

       $.ajax({
          url: "/search_stock/product_breakdown",
          type: "POST", dataType: "json", contentType: "application/json",
          data: JSON.stringify({jsonrpc: "2.0", method: "call", params: { product_id: pid, warehouse_id: currentWid, detail_mode: detailMode }, id: 1}),
          success: function(resp) {
              var res = (resp && resp.result) ? resp.result : {};
              if(res.ok) {
                 $detail.find('td').html(buildDetailTable(res));
              } else {
                 $detail.find('td').html('<div class="text-danger small">Lỗi: ' + (res.error || 'Unknown') + '</div>');
              }
          }
       });
    });
  });

  // Helper render bảng chi tiết
  function fmt(n) { return (parseFloat(n)||0).toLocaleString('en-US'); }
  function buildDetailTable(data) {
      var html = '<div class="border rounded bg-light p-2"><table class="table table-sm table-borderless mb-0 small">';
      var rows = data.rows || [];
      if(data.mode === 'components_by_warehouse') {
          html += '<thead class="text-muted border-bottom"><tr><th colspan="2">Thành phần</th><th class="text-end">SL/Combo</th><th class="text-end">Tồn kho</th><th class="text-end">Khả dụng</th></tr></thead><tbody>';
          rows.forEach(function(c){
              html += '<tr><td colspan="5" class="fw-bold pt-2 text-primary">' + c.name + ' <span class="text-muted fw-normal ms-1">(' + c.default_code + ')</span></td></tr>';
              (c.warehouses||[]).forEach(function(w){
                  html += '<tr><td style="width:15px;"></td><td>↳ ' + w.warehouse_name + '</td><td class="text-end">' + fmt(c.component_qty_in_combo) + '</td><td class="text-end">' + fmt(w.qty_total) + '</td><td class="text-end fw-bold text-success">' + fmt(w.qty_available) + '</td></tr>';
              });
          });
      } else {
          html += '<thead class="text-muted border-bottom"><tr><th>Kho hàng</th><th class="text-end">Tồn thực tế</th><th class="text-end">Đã giữ</th><th class="text-end">Khả dụng</th></tr></thead><tbody>';
          rows.forEach(function(r){
              html += '<tr><td>' + r.warehouse_name + '</td><td class="text-end">' + fmt(r.qty_total) + '</td><td class="text-end text-muted">' + fmt(r.qty_reserved) + '</td><td class="text-end fw-bold text-success">' + fmt(r.qty_available) + '</td></tr>';
          });
      }
      html += '</tbody></table></div>';
      return html;
  }

})();
